package com.certmanage.server;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.sun.net.httpserver.HttpServer;import java.net.InetSocketAddress;import java.util.concurrent.atomic.AtomicReference;
class RemoteTransportTest {
 @Test void binaryAndSafeTestAndResponseCheck()throws Exception{var target=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var method=new AtomicReference<String>();var received=new AtomicReference<byte[]>();target.createContext("/",exchange->{method.set(exchange.getRequestMethod());received.set(exchange.getRequestBody().readAllBytes());byte[] response="{\"ok\":\"yes\"}".getBytes();exchange.sendResponseHeaders(200,exchange.getRequestMethod().equals("HEAD")?-1:response.length);if(!exchange.getRequestMethod().equals("HEAD"))exchange.getResponseBody().write(response);exchange.close();});target.start();try{var servers=mock(ServerService.class);var config=new HashMap<String,Object>(Map.of("type","HTTP","baseUrl","http://127.0.0.1:"+target.getAddress().getPort(),"connectTimeout",2,"readTimeout",2));when(servers.connection(1)).thenReturn(config);when(servers.enabled(1)).thenReturn(true);when(servers.snapshot(1)).thenReturn(Map.of("configId",1L));var transport=new RemoteTransport(servers,new ObjectMapper());assertEquals(true,transport.test(1).get("success"));assertEquals("HEAD",method.get());transport.execute(1,1,Map.of("path","/","method","PUT","jsonPath","ok","expectedValue","yes"),new byte[]{1,2},"a.bin");assertArrayEquals(new byte[]{1,2},received.get());assertThrows(IllegalArgumentException.class,()->transport.execute(1,1,Map.of("path","//evil.invalid/"),new byte[0],"a"));assertThrows(IllegalArgumentException.class,()->transport.execute(1,1,Map.of("path","/","jsonPath","ok","expectedValue","no"),new byte[0],"a"));}finally{target.stop(0);}}
 @Test void standardGetAndFormRequest()throws Exception{var target=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var seen=new AtomicReference<String>();target.createContext("/",e->{seen.set(e.getRequestMethod()+"|"+e.getRequestURI()+"|"+e.getRequestHeaders().getFirst("X-Test")+"|"+new String(e.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));e.sendResponseHeaders(200,-1);e.close();});target.start();try{var service=mock(ServerService.class);when(service.enabled(1)).thenReturn(true);when(service.connection(1)).thenReturn(new HashMap<>(Map.of("type","HTTP","baseUrl","http://127.0.0.1:"+target.getAddress().getPort(),"connectTimeout",2,"readTimeout",2)));var transport=new RemoteTransport(service,new ObjectMapper());transport.execute(1,1,Map.of("method","GET","path","/health","bodyMode","NONE","query",Map.of("q","a b"),"headers",Map.of("X-Test","yes")),null,"unused");assertEquals("GET|/health?q=a+b|yes|",seen.get());transport.execute(1,1,Map.of("method","DELETE","path","/item","bodyMode","FORM","fields",Map.of("name","a b")),null,"unused");assertTrue(seen.get().endsWith("|name=a+b"));}finally{target.stop(0);}}
 @Test void stalledResponseBodyHonorsDeadline()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var release=new java.util.concurrent.CountDownLatch(1);server.createContext("/",e->{e.sendResponseHeaders(200,100);e.getResponseBody().write(1);e.getResponseBody().flush();try{release.await(5,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}e.close();});server.start();try{var service=mock(ServerService.class);when(service.enabled(1)).thenReturn(true);when(service.connection(1)).thenReturn(new HashMap<>(Map.of("type","HTTP","baseUrl","http://127.0.0.1:"+server.getAddress().getPort(),"connectTimeout",1,"readTimeout",1)));var transport=new RemoteTransport(service,new ObjectMapper());long start=System.nanoTime();var timeout=assertThrows(RemoteFailure.class,()->transport.execute(1,1,Map.of("path","/"),new byte[0],"a"));assertEquals("TIMEOUT",timeout.code());assertTrue(java.time.Duration.ofNanos(System.nanoTime()-start).toMillis()<3500);}finally{release.countDown();server.stop(0);}} @Test void preservesBasePrefixAndRejectsEncodedTraversal()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var path=new AtomicReference<String>();server.createContext("/",e->{path.set(e.getRequestURI().getPath());e.sendResponseHeaders(200,-1);e.close();});server.start();try{var service=mock(ServerService.class);when(service.enabled(1)).thenReturn(true);when(service.snapshot(1)).thenReturn(Map.of("configId",1L));when(service.connection(1)).thenReturn(new HashMap<>(Map.of("type","HTTP","baseUrl","http://127.0.0.1:"+server.getAddress().getPort()+"/api/","connectTimeout",1,"readTimeout",1,"testPath","/health")));var transport=new RemoteTransport(service,new ObjectMapper());assertEquals(true,transport.test(1).get("success"));assertEquals("/api/health",path.get());transport.execute(1,1,Map.of("path","/import"),new byte[0],"a");assertEquals("/api/import",path.get());for(String invalid:List.of("/%2e%2e/escape","/%252e%252e/escape","//other/","/import#fragment","/%2f%2fother"))assertThrows(IllegalArgumentException.class,()->transport.execute(1,1,Map.of("path",invalid),new byte[0],"a"));}finally{server.stop(0);}}}


